// Reuse the real, synthetic-credential protobuf captures also exercised by the
// Python ingestion tests. Generated by traceAI's csharp/tests/AnthropicNativeContract
// loopback contract at the first tracing release and current published release.
func loadAnthropicFixture(t *testing.T, version, scenario string) ptrace.Traces {
	t.Helper()
	path := filepath.Join("../../../futureagi/tracer/tests/fixtures/anthropic_csharp", version+"-"+scenario+".pb")
	body, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	var decoder ptrace.ProtoUnmarshaler
	traces, err := decoder.UnmarshalTraces(body)
	if err != nil {
		t.Fatal(err)
	}
	for i := 0; i < traces.ResourceSpans().Len(); i++ {
		attrs := traces.ResourceSpans().At(i).Resource().Attributes()
		attrs.PutStr("fi.project_id", orProjectID)
		attrs.PutStr("fi.org_id", orOrgID)
	}
	return traces
}

func TestAnthropicNativeCaptures(t *testing.T) {
	for _, version := range []string{"12.56.0", "13.3.0"} {
		for _, scenario := range []string{"content", "binary-content", "truncation", "concurrent", "tool-content", "tool-metadata"} {
			t.Run(version+"/"+scenario, func(t *testing.T) {
				traces := loadAnthropicFixture(t, version, scenario)
				// The shared qualifier prepares once; conversion must be idempotent.
				normalization.Prepare(traces)
				before, _ := (&ptrace.ProtoMarshaler{}).MarshalTraces(traces)
				rows, ids, err := ConvertWithIdentities(context.Background(), traces, nil)
				if err != nil {
					t.Fatal(err)
				}
				after, _ := (&ptrace.ProtoMarshaler{}).MarshalTraces(traces)
				if string(before) != string(after) {
					t.Fatal("converter mutated the source trace")
				}
				counts := map[string]int{}
				byID := rowsByID(t, rows)
				for _, row := range rows {
					counts[row["observation_type"].(string)]++
					if row["observation_type"] == "llm" {
						if row["prompt_tokens"] != int32(12) || row["total_tokens"] != int32(17) {
							t.Errorf("cached input must be counted once: %v/%v", row["prompt_tokens"], row["total_tokens"])
						}
						if row["status"] != "OK" || row["provider"] != "anthropic" || row["model"] != "claude-opus-5-5" {
							t.Errorf("model metadata: %v/%v/%v", row["status"], row["provider"], row["model"])
						}
						switch scenario {
						case "content", "binary-content":
							var messages []map[string]any
							if err := json.Unmarshal([]byte(row["input"].(string)), &messages); err != nil || len(messages) != 2 || messages[0]["role"] != "system" {
								t.Fatalf("input must start with system instructions: %v (%v)", row["input"], err)
							}
							for _, sentinel := range []string{"SYSTEM_SENTINEL", "PROMPT_SENTINEL"} {
								if !strings.Contains(row["input"].(string), sentinel) {
									t.Errorf("missing %s", sentinel)
								}
							}
							if !strings.Contains(row["output"].(string), "RESPONSE_SENTINEL") {
								t.Error("missing response")
							}
						case "truncation":
							if strings.Contains(row["input"].(string), "SENTINEL") {
								t.Error("truncated input was reconstructed")
							}
						case "concurrent":
							parent := byID[row["parent_span_id"].(string)]
							want := detid.TraceSessionID(orProjectID, parent["name"].(string)).String()
							if row["trace_session_id"] != want {
								t.Errorf("session = %v, want %s for %v", row["trace_session_id"], want, parent["name"])
							}
						}
					}
					if scenario == "tool-metadata" || scenario == "concurrent" {
						if row["input"] != "" || row["output"] != "" {
							t.Error("metadata-only span gained content")
						}
					}
					if scenario == "tool-content" && row["observation_type"] == "tool" {
						if row["input"] != "{}" || !strings.Contains(row["output"].(string), "TOOL_RESULT_SENTINEL") {
							t.Errorf("tool content lost: %v / %v", row["input"], row["output"])
						}
					}
				}
				if strings.HasPrefix(scenario, "tool-") {
					if counts["llm"] != 2 || counts["agent"] != 1 || counts["tool"] != 1 || len(rows) != 5 {
						t.Errorf("runner hierarchy types: %v", counts)
					}
					for _, row := range rows {
						if row["observation_type"] == "llm" || row["observation_type"] == "tool" {
							if byID[row["parent_span_id"].(string)]["observation_type"] != "agent" {
								t.Error("model/tool parent must be the runner")
							}
						}
					}
				}
				if scenario == "concurrent" {
					if len(ids.Sessions()) != 2 {
						t.Fatalf("curated sessions=%d, want 2", len(ids.Sessions()))
					}
					for _, session := range ids.Sessions() {
						if session.TraceSessionID != detid.TraceSessionID(orProjectID, session.ExternalSessionID).String() {
							t.Error("curated/span identity drift")
						}
					}
				}
			})
		}
	}
}

func TestNativeContentAliasPrecedence(t *testing.T) {
	for _, direction := range []string{"input", "output"} {
		for _, alias := range []string{direction + ".value", "fi.llm." + direction, "raw." + direction, "span." + direction, map[string]string{"input": "gen_ai.prompt", "output": "gen_ai.completion"}[direction]} {
			for _, value := range []any{"", nil, "__REDACTED__", false, int64(0), map[string]any{"safe": true}} {
				t.Run(alias+"/"+fmtValue(value), func(t *testing.T) {
					row := convertOne(t, contentSpan(func(attrs pcommon.Map) {
						_ = attrs.FromRaw(map[string]any{
							"gen_ai.operation.name": "execute_tool", alias: value,
							"gen_ai.input.messages":         `[{"role":"user","parts":[{"type":"text","content":"RAW_SENTINEL"}]}]`,
							"gen_ai.system_instructions":    `[{"type":"text","content":"SYSTEM_SENTINEL"}]`,
							"gen_ai.output.messages":        "RAW_SENTINEL",
							"gen_ai.tool.call.arguments":    "RAW_SENTINEL",
							"anthropic.tool_result.content": "RAW_SENTINEL",
						})
					}))
					if got, want := row[direction], fmtValue(value); got != want {
						t.Errorf("%s=%v, want %v", direction, got, want)
					}
				})
			}
		}
	}
}

func fmtValue(value any) string {
	if value == nil {
		return ""
	}
	if s, ok := value.(string); ok {
		return s
	}
	data, _ := json.Marshal(value)
	return string(data)
}

func TestNativeToolValuesAndKindPrecedence(t *testing.T) {
	for _, value := range []any{false, int64(0), int64(9007199254740993), "", nil, "{}", map[string]any{"n": int64(9007199254740993)}, []any{map[string]any{"type": "text", "text": "result"}}} {
		t.Run(fmtValue(value), func(t *testing.T) {
			row := convertOne(t, contentSpan(func(attrs pcommon.Map) {
				_ = attrs.FromRaw(map[string]any{"gen_ai.operation.name": "execute_tool", "gen_ai.tool.call.arguments": value, "gen_ai.tool.call.result": value, "anthropic.tool_result.content": "STALE_RESULT"})
			}))
			if row["input"] != fmtValue(value) || row["output"] != fmtValue(value) {
				t.Errorf("tool value not preserved: %v/%v", row["input"], row["output"])
			}
		})
	}
	for _, key := range spanKindAttrKeys {
		t.Run(key, func(t *testing.T) {
			row := convertOne(t, contentSpan(func(attrs pcommon.Map) {
				attrs.PutStr(key, "chain")
				attrs.PutStr("gen_ai.operation.name", "invoke_agent")
			}))
			if row["observation_type"] != "chain" {
				t.Error("operation overrode explicit kind")
			}
		})
	}
}

func TestNativeConversationFallback(t *testing.T) {
	cases := []struct {
		name  string
		attrs map[string]any
		want  *string
	}{
		{"conversation", map[string]any{"gen_ai.conversation.id": "conversation"}, stringPtr("conversation")},
		{"explicit", map[string]any{"gen_ai.conversation.id": "conversation", "session.id": "explicit"}, stringPtr("explicit")},
		{"explicit empty", map[string]any{"gen_ai.conversation.id": "conversation", "session.id": ""}, stringPtr("")},
		{"explicit zero", map[string]any{"gen_ai.conversation.id": "conversation", "session.id": int64(0)}, stringPtr("0")},
		{"empty conversation", map[string]any{"gen_ai.conversation.id": ""}, nil},
		{"numeric conversation", map[string]any{"gen_ai.conversation.id": int64(0)}, nil},
		{"absent", map[string]any{}, nil},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			traces := contentSpan(func(attrs pcommon.Map) { _ = attrs.FromRaw(tc.attrs) })
			traces.ResourceSpans().At(0).ScopeSpans().At(0).Scope().SetName("com.anthropic.sdk.csharp")
			traces.ResourceSpans().At(0).ScopeSpans().At(0).Scope().SetVersion("13.3.0")
			traces.ResourceSpans().At(0).Resource().Attributes().PutStr("fi.project_id", orProjectID)
			rows, ids, err := ConvertWithIdentities(context.Background(), traces, nil)
			if err != nil {
				t.Fatal(err)
			}
			if tc.want == nil {
				if rows[0]["trace_session_id"] != nil || len(ids.Sessions()) != 0 {
					t.Fatal("unexpected session")
				}
				return
			}
			wantID := detid.TraceSessionID(orProjectID, *tc.want).String()
			if rows[0]["trace_session_id"] != wantID || len(ids.Sessions()) != 1 || ids.Sessions()[0].ExternalSessionID != *tc.want || ids.Traces()[0].SessionID != wantID {
				t.Errorf("span/session/trace identity mismatch: %v/%v/%v", rows[0]["trace_session_id"], ids.Sessions(), ids.Traces())
			}
		})
	}
}

func stringPtr(s string) *string { return &s }
